import "https://cdn.jsdelivr.net/npm/@alicloud/dingtalk-react@latest"
const scanResult = {
  target: '127.0.0.1',
  openPorts: [135, 445],
  timestamp: '2026-05-10T07:50:09.422Z'
}

// Function to generate KQL code from scan result
function generateKqlCode(scanResult) {
  let kqlOutput = `import "https://cdn.jsdelivr.net/npm/@alicloud/dingtalk-react@latest"
snippet:
{
  target: ${scanResult.target},
  openPorts: [${scanResult.openPorts.join(", ")}],
  timestamp: ${scanResult.timestamp}
}`;

  // Output the KQL code snippet
  return kqlOutput;
}

// Example usage: Generate and output KQL code for scan result data
const generatedKqlCode = generateKqlCode(scanResult);
console.log(generatedKqlCode);
```

